fn prime_num(n: u64) -> bool {
    // By assumption n >= 2
    // 2 and 3 are prime
    if n <= 3 {
        return true;
    }
    // eliminate even numbers > 2
    if n % 2 == 0 {
        return false;
    }
    // trial divide by odd numbers up to sqrt(n)
    let mut i = 3;
    while i <= n / i {
        if n % i == 0 {
            return false;
        }
        i += 2;
    }
    true
}

